//! Translation keys of 1.13 text components for a 1.12.2 client.
//!
//! 1.13 renamed most keys; a 1.12.2 client shows a key it does not know as
//! the key itself. `data/down_translations.json` (generated by
//! `data/down_translations.py` from both server jars' English language
//! files) names, for every key 1.12.2 lacks, a 1.12.2 key with the same
//! English text, or else the English text to show literally.
//!
//! INTEGRATION: the text codec converts components; it should call
//! [`legacy_translation`] for each `translate` key of components on their
//! way from 1.13 to 1.12.2 (a re-export from `steps/mod.rs` makes it
//! reachable from `codec::text`). With [`Legacy::Text`], the component
//! becomes literal text with its `with` arguments substituted for the
//! `%s` / `%1$s` placeholders.
#![cfg_attr(not(test), allow(dead_code))]
use serde::Deserialize;
use std::{collections::HashMap, sync::OnceLock};

/// What a 1.12.2 client should get for a 1.13 translation key.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Legacy {
    /// The 1.12.2 key with the same English text.
    Key(&'static str),
    /// No 1.12.2 key says this; the 1.13 English text.
    Text(&'static str),
}

#[derive(Deserialize)]
struct Table {
    renames: HashMap<String, String>,
    fallback: HashMap<String, String>,
}

fn table() -> &'static Table {
    static TABLE: OnceLock<Table> = OnceLock::new();
    TABLE.get_or_init(|| {
        serde_json::from_str(include_str!("../data/down_translations.json"))
            .expect("down_translations.json is valid")
    })
}

/// The 1.12.2 form of the 1.13 translation key `key`; `None` when 1.12.2
/// knows the key itself (or it is not a vanilla key).
pub fn legacy_translation(key: &str) -> Option<Legacy> {
    let table = table();
    if let Some(old) = table.renames.get(key) {
        return Some(Legacy::Key(old));
    }
    table.fallback.get(key).map(|text| Legacy::Text(text))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn renamed_keys_find_the_1_12_key_of_the_same_text() {
        assert_eq!(
            legacy_translation("block.minecraft.stone"),
            Some(Legacy::Key("tile.stone.stone.name"))
        );
        assert_eq!(
            legacy_translation("item.minecraft.diamond_sword"),
            Some(Legacy::Key("item.swordDiamond.name"))
        );
        assert_eq!(
            legacy_translation("entity.minecraft.zombie"),
            Some(Legacy::Key("entity.Zombie.name"))
        );
        // Unchanged keys and keys outside the game need nothing.
        assert_eq!(legacy_translation("chat.type.text"), None);
        assert_eq!(legacy_translation("death.attack.drown"), None);
        assert_eq!(legacy_translation("plugin.message"), None);
        // New content has no 1.12 key: its English text stands in.
        assert_eq!(
            legacy_translation("block.minecraft.tube_coral"),
            Some(Legacy::Text("Tube Coral"))
        );
    }
}
